begin;
create temp table assertion_count(n int);insert into assertion_count values(0);
create function pg_temp.check_it(v boolean,label text)returns void language plpgsql as $$begin if v is distinct from true then raise exception 'Assertion failed: %',label;end if;update assertion_count set n=n+1;end$$;
create function pg_temp.throws(statement text,label text)returns void language plpgsql as $$declare failed boolean:=false;begin begin execute statement;exception when others then failed:=true;end;perform pg_temp.check_it(failed,label);end$$;
create function pg_temp.i(n int)returns uuid language sql immutable as $$select('ee890000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create temp table st(k text primary key,v jsonb);grant all on st,assertion_count to service_role;
insert into public.organizations(id,name)values(pg_temp.i(1),'Brain contact fixture'),(pg_temp.i(2),'Foreign contact fixture');
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at)select pg_temp.i(n),'00000000-0000-0000-0000-000000000000','authenticated','authenticated','brain-contact-'||n||'@fixture.invalid',clock_timestamp(),clock_timestamp(),clock_timestamp()from generate_series(101,102)n;
insert into public.profiles(id,org_id,role)select pg_temp.i(n),pg_temp.i(n-100),'admin' from generate_series(101,102)n on conflict(id)do update set org_id=excluded.org_id,role=excluded.role;
insert into public.properties(id,org_id,name)values(pg_temp.i(201),pg_temp.i(1),'Community A'),(pg_temp.i(202),pg_temp.i(1),'Same organization community B'),(pg_temp.i(203),pg_temp.i(2),'Foreign community');
select public.brain_set_access(pg_temp.i(101),pg_temp.i(201),pg_temp.i(101),array['read','manage'],null,false,'Explicit fixture community authority');
insert into public.lumaleasing_config(id,property_id,api_key,is_active)values(pg_temp.i(301),pg_temp.i(201),'brain-contact-synthetic-key',true);
insert into public.widget_sessions(id,property_id,visitor_id,last_activity_at)values(pg_temp.i(350),pg_temp.i(201),'brain-contact-visitor',clock_timestamp());
insert into public.leads(id,property_id,first_name,email,source,status)values(pg_temp.i(401),pg_temp.i(201),'Visitor','a@fixture.invalid','widget','new'),(pg_temp.i(402),pg_temp.i(202),'Sibling','b@fixture.invalid','widget','new'),(pg_temp.i(403),pg_temp.i(203),'Foreign','c@fixture.invalid','widget','new'),(pg_temp.i(404),pg_temp.i(201),'Other','d@fixture.invalid','widget','new');
insert into public.conversations(id,property_id,widget_session_id,channel)values(pg_temp.i(451),pg_temp.i(201),pg_temp.i(350),'widget');
create function pg_temp.link(lead_id int default 401)returns jsonb language sql as $$select public.link_luma_visitor_lead(pg_temp.i(201),pg_temp.i(501),(select(v->>'token')::uuid from st where k='request'),pg_temp.i(350),pg_temp.i(451),pg_temp.i(lead_id))$$;
set local role service_role;
insert into st values('request',public.claim_recorded_luma_request(pg_temp.i(201),pg_temp.i(501),'lead',jsonb_build_object('sessionId',pg_temp.i(350),'email','a@fixture.invalid')::text,'fixture',encode(sha256(convert_to('brain-contact-synthetic-key','UTF8')),'hex')));
select pg_temp.check_it(pg_temp.link()->>'state'='saved','verified visitor links without inventing a human actor');
select pg_temp.check_it((select lead_id=pg_temp.i(401)from public.widget_sessions where id=pg_temp.i(350))and(select lead_id=pg_temp.i(401)from public.conversations where id=pg_temp.i(451)),'session and conversation link atomically');
select pg_temp.check_it((select count(*)=1 from public.lead_engagement_events where lead_id=pg_temp.i(401)and event_type='chat_started'),'one source engagement');
select pg_temp.check_it((select count(*)=1 from public.lead_engagement_receipts where lead_id=pg_temp.i(401)and origin='lumaleasing'and actor_id is null),'source receipt has no fabricated actor');
select pg_temp.check_it((select count(*)=1 from public.shared_action_events where property_id=pg_temp.i(201)and action='lead.engagement.recorded'and actor_id is null and service_principal='leadpulse.source_service'and not training_eligible),'audited service evidence excluded from training');
select pg_temp.check_it((select count(*)>0 from public.lead_scores where lead_id=pg_temp.i(401)),'score committed with linkage');
select pg_temp.check_it(pg_temp.link()->>'state'='saved','link replay succeeds');
select pg_temp.check_it((select count(*)=1 from public.lead_engagement_events where lead_id=pg_temp.i(401)and event_type='chat_started'),'retry does not double-score');
select pg_temp.check_it(pg_temp.link(402)->>'state'='not_found','same-organization foreign community contact denied');
select pg_temp.check_it(pg_temp.link(403)->>'state'='not_found','foreign organization contact denied');
select pg_temp.check_it(pg_temp.link(404)->>'state'='contact_conflict','existing visitor contact cannot be replaced');
select pg_temp.check_it(public.link_luma_visitor_lead(pg_temp.i(201),pg_temp.i(501),pg_temp.i(999),pg_temp.i(350),pg_temp.i(451),pg_temp.i(401))->>'state'='authority_changed','wrong lease denied');
select pg_temp.check_it(public.record_lead_engagement(pg_temp.i(201),pg_temp.i(401),'chat_started',jsonb_build_object('conversation_id',pg_temp.i(999),'source','lumaleasing_widget'),'luma/chat-started/'||pg_temp.i(999)||'/'||pg_temp.i(401),'lumaleasing',null)->>'state'='forbidden','fabricated conversation denied');
select pg_temp.check_it(public.record_lead_engagement(pg_temp.i(202),pg_temp.i(402),'chat_started',jsonb_build_object('conversation_id',pg_temp.i(451),'source','lumaleasing_widget'),'luma/chat-started/'||pg_temp.i(451)||'/'||pg_temp.i(402),'lumaleasing',null)->>'state'='forbidden','foreign conversation ancestry denied');
select pg_temp.check_it(public.record_lead_engagement(pg_temp.i(201),pg_temp.i(401),'chat_started',jsonb_build_object('conversation_id',pg_temp.i(451),'source','lumaleasing_widget'),'forged-key','lumaleasing',null)->>'state'='forbidden','event identity bound to retained conversation');
select pg_temp.check_it(public.record_lead_engagement(pg_temp.i(201),pg_temp.i(401),'tour_completed','{}','forged-event','lumaleasing',null)->>'state'='forbidden','source exception does not authorize other events');
select pg_temp.check_it(public.record_lead_engagement(pg_temp.i(201),pg_temp.i(401),'call_inbound','{}','foreign-operator','operator',pg_temp.i(102))->>'state'='forbidden','operator still requires community permission');
select pg_temp.check_it(public.record_lead_engagement(pg_temp.i(201),pg_temp.i(401),'call_inbound','{}','valid-operator','operator',pg_temp.i(101))->>'state'='applied','authorized operator path preserved');
select pg_temp.check_it(not has_function_privilege('anon','public.record_lead_engagement(uuid,uuid,text,jsonb,text,text,uuid)','EXECUTE')and not has_function_privilege('authenticated','public.record_lead_engagement(uuid,uuid,text,jsonb,text,text,uuid)','EXECUTE')and not has_function_privilege('community_brain_worker','public.record_lead_engagement(uuid,uuid,text,jsonb,text,text,uuid)','EXECUTE'),'no new public or worker grant');
select pg_temp.check_it(not has_function_privilege('service_role','public._brain_record_lead_engagement(uuid,uuid,text,jsonb,text,text,uuid)','EXECUTE'),'private implementation remains inaccessible');
reset role;
create function pg_temp.reject_contact_action()returns trigger language plpgsql as $$begin if new.property_id=pg_temp.i(201)and new.action='lead.engagement.recorded'then raise exception 'Fixture audit failure';end if;return new;end$$;
create trigger brain_contact_fixture_action before insert on public.shared_action_events for each row execute function pg_temp.reject_contact_action();
set local role service_role;
select pg_temp.throws('insert into public.conversations(id,property_id,lead_id,channel)values(pg_temp.i(460),pg_temp.i(201),pg_temp.i(401),''widget'')','source fails when audit cannot be saved');
select pg_temp.check_it(not exists(select 1 from public.conversations where id=pg_temp.i(460))and not exists(select 1 from public.lead_engagement_receipts where request_key='luma/chat-started/'||pg_temp.i(460)||'/'||pg_temp.i(401)),'audit failure leaves no partial conversation or receipt');
reset role;
select 'Assertions passed: '||n from assertion_count;
rollback;
